   [30]={next_id=31, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="特拉西看向你，眼中充满不解与困惑。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [31]={next_id=32, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你是怎么发现芒刺是我假扮的，明明连蛰吻都分辨不出来。", msg_color="", msg_size=0, talker="特拉西", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [32]={next_id=33, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="破绽从头到尾都摆在明面上。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [33]={next_id=34, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你可以模仿芒刺的容貌、语气、过往细节，但你模仿不了她刻入骨髓的初心。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [34]={next_id=35, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你用来动摇蛰吻的那套强权歪理，从根本上就和芒刺的三观相悖，这是你最大的败笔。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [35]={next_id=36, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="其次，你们发给矿工们的绿色精力剂具有致幻的效果，其味道是带有丝丝的甜味。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [36]={next_id=37, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而不管是在之前的实验室，还是在上方的通道里，都有那种奇怪的甜味。并且我们都吸入过大量的粉末。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [37]={next_id=38, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以我们在进入通道的那一刻就中了幻觉，就连之前在矿洞实验室里出现的那个芒刺，也是幻觉。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="最后一点则是——我根本就不相信什么人可以起死回生。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你的话语铿锵，字字都像是巨锤落在特拉西的心头上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [40]={next_id=41, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不得不承认，莱斯坦斯的链尉官，你的洞察力远超我的预料。", msg_color="", msg_size=0, talker="特拉西", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [41]={next_id=42, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我本打算借花粉制造的幻象，让你们自乱阵脚，最后悄无声息化作源晶花的养料。没想到，最后竟是功亏一篑。", msg_color="", msg_size=0, talker="特拉西", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [42]={next_id=43, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="特拉西看向蛰吻，目光带着浓浓的恨意。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [43]={next_id=44, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻，还记得我是谁吗？十年前，你摧毁了我的影巢。", msg_color="", msg_size=0, talker="特拉西", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [44]={next_id=45, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你是……影巢的首领！", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [45]={next_id=46, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="没错。", msg_color="", msg_size=0, talker="特拉西", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [46]={next_id=47, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="一切的问题都在蛰吻脑子里面串联了起来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [47]={next_id=48, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="原来是你，怪不得我会处处遭到针对，怪不得在矿区的秘密实验室的时候我的毒对你不起作用。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [48]={next_id=49, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="十年前，你摧毁了影巢。很不巧，那时候源晶树正处于枯萎期的关键时期。", msg_color="", msg_size=0, talker="特拉西", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [49]={next_id=50, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="因为你的破坏，导致它没有吸收足够多的虚粒子，变成的种子也不完全。", msg_color="", msg_size=0, talker="特拉西", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [50]={next_id=51, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当时我深受重伤，濒临死亡的我把那颗不完全的种子塞进体内。", msg_color="", msg_size=0, talker="特拉西", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [51]={next_id=52, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="虽然我活了下来，但因为种子的不完全，结果把我变成了这种半人半怪物的样子。", msg_color="", msg_size=0, talker="特拉西", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [52]={next_id=53, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="特拉西身体外的黑雾翻滚的更加剧烈，眼中的仇恨变得愈发深沉。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [53]={next_id=54, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我逃到了这里，蛰伏数年，寻找重建影巢的机会。但我知道，仅凭我一人无法实现这个目的，每一个蜂巢都是由千万只蜜蜂共同构建的。", msg_color="", msg_size=0, talker="特拉西", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
