   [73]={next_id=74, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我幼年被遗弃在影巢最底层的贫民窟，饿到啃食霉变矿渣，寒冬腊月只能蜷缩在排污管道里御寒。", msg_color="", msg_size=0, talker="特拉西", audio="", img="arts/ui/bg/story/storybg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7215", 0, 0, 104, 224.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
